import React, { useState } from "react";
import { createDelivery } from "../api/deliveryApi";
import { useNavigate } from "react-router-dom";

export default function CreateDeliveryForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    customerId: "",
    driverId: "",
    lat: "",
    lng: "",
    status: "Assigned"
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await createDelivery({
        customerId: form.customerId,
        driverId: form.driverId,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
        status: form.status
      });
      alert("✅ Delivery created successfully!");
      setForm({ customerId: "", driverId: "", lat: "", lng: "", status: "Assigned" });
    } catch (error) {
      console.error("Error creating delivery:", error);
      alert("❌ Failed to create delivery");
    }
  };

  const styles = {
    form: {
      padding: "30px",
      maxWidth: "400px",
      margin: "auto",
      backgroundColor: "#f9f9f9",
      border: "1px solid #ddd",
      borderRadius: "8px",
      boxShadow: "0 2px 6px rgba(0,0,0,0.1)"
    },
    input: {
      width: "100%",
      padding: "10px",
      marginBottom: "15px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      fontSize: "16px"
    },
    select: {
      width: "100%",
      padding: "10px",
      marginBottom: "15px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      fontSize: "16px"
    },
    button: {
      padding: "10px 20px",
      fontSize: "16px",
      backgroundColor: "#007bff",
      color: "#fff",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer"
    },
    backButton: {
      padding: "10px 20px",
      marginTop: "15px",
      backgroundColor: "#6c757d",
      color: "#fff",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer"
    }
  };

  return (
    <form onSubmit={handleSubmit} style={styles.form}>
      <h2 style={{ marginBottom: "20px", textAlign: "center" }}>Create Delivery</h2>

      <input
        style={styles.input}
        type="text"
        name="customerId"
        placeholder="Customer ID"
        value={form.customerId}
        onChange={handleChange}
        required
      />

      <input
        style={styles.input}
        type="text"
        name="driverId"
        placeholder="Driver ID"
        value={form.driverId}
        onChange={handleChange}
        required
      />

      <input
        style={styles.input}
        type="text"
        name="lat"
        placeholder="Latitude"
        value={form.lat}
        onChange={handleChange}
        required
      />

      <input
        style={styles.input}
        type="text"
        name="lng"
        placeholder="Longitude"
        value={form.lng}
        onChange={handleChange}
        required
      />

      <select
        style={styles.select}
        name="status"
        value={form.status}
        onChange={handleChange}
      >
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>

      <button type="submit" style={styles.button}>
        Create Delivery
      </button>

      <button type="button" style={styles.backButton} onClick={() => navigate("/")}>
        ← Back to Dashboard
      </button>
    </form>
  );
}
